#!/bin/bash
# TiDE on PEMS03: input 96, horizons 12 24 48 96; settings of the official scripts, protocol of the official loaders.
# Generated by scripts/multivariate_forecasting/make_scripts.py: change the profile and generate again.
#   bash scripts/multivariate_forecasting/PEMS/TiDE_PEMS03.sh                                   seeds 2021 2022 2023
#   SEEDS="2021" EXTRA_ARGS="--no_use_gpu --num_workers 0" bash scripts/multivariate_forecasting/PEMS/TiDE_PEMS03.sh   one seed on the CPU
# Results: output/long_term_forecast/PEMS03.tsv (one row per run); checkpoints: temp/checkpoints/PEMS03/.
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
cd "$(dirname "$0")/../../.."
root="$(python -m src.utils.paths root PEMS03.npz)/"
seeds=(${SEEDS:-2021 2022 2023})

# horizon 12: scripts/benchmark/official/TSLib/ETT_script/TiDE_ETTh1.sh (ETTh1 configuration, horizon 96)
for seed in "${seeds[@]}"; do
  python -u scripts/run.py \
    --is_training 1 \
    --model TiDE \
    --des PEMS03_12_TiDE \
    --seed "$seed" \
    --root_path "$root" \
    --data_path PEMS03.npz \
    --data PEMS \
    --model_id PEMS03_96_12 \
    --features M \
    --seq_len 96 \
    --label_len 48 \
    --pred_len 12 \
    --enc_in 358 \
    --dec_in 358 \
    --c_out 358 \
    --freq h \
    --drop_last \
    --test_batch_size 1 \
    --no_time_marks \
    --e_layers 2 \
    --d_layers 2 \
    --d_model 256 \
    --d_ff 256 \
    --dropout 0.3 \
    --batch_size 512 \
    --learning_rate 0.1 \
    --patience 5 \
    --train_epochs 10 \
    --c_out 8 \
    --tide_checkpoint \
    $EXTRA_ARGS
done

